  ('head', 'Head of department', 'رئيس القسم', 20, false),
  ('manager', 'Manager', 'مدير', 30, false),
  ('member', 'Team member', 'عضو الفريق', 40, false),
  ('viewer', 'Viewer', 'مشاهد', 50, false)
on conflict (key) do nothing;

